/* Allo — Service Worker dédié aux notifications Push (placer à côté de index.html) */
const ICON = "data:image/png;base64,";
self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', e => e.waitUntil(self.clients.claim()));

self.addEventListener('push', event => {
  let d = {};
  try { d = event.data ? event.data.json() : {}; } catch (_) { try { d = { body: event.data.text() }; } catch (__) {} }
  const opts = {
    body: d.body || '', icon: ICON, badge: ICON,
    tag: d.tag || undefined, renotify: !!d.tag,
    vibrate: [120, 60, 120],
    data: { url: d.url || '/', kind: d.kind }
  };
  if (d.image) opts.image = d.image;
  event.waitUntil((async () => {
    const wins = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    const focused = wins.find(w => w.visibilityState === 'visible' && w.focused);
    const safari = /^((?!chrome|android).)*safari/i.test(self.navigator.userAgent);
    if (focused && !safari) { focused.postMessage({ type: 'allo-push', payload: d }); return; }
    await self.registration.showNotification(d.title || 'Allo', opts);
  })());
});

self.addEventListener('notificationclick', event => {
  event.notification.close();
  const base = new URL('./', self.location.href);
  const target = new URL(String((event.notification.data && event.notification.data.url) || './').replace(/^\//, ''), base);
  event.waitUntil((async () => {
    const wins = (await self.clients.matchAll({ type: 'window', includeUncontrolled: true }))
      .filter(w => new URL(w.url).origin === self.location.origin);
    const c = wins.find(w => w.focused) || wins[0];
    if (c) { try { await c.focus(); } catch (_) {} c.postMessage({ type: 'allo-push-open', url: target.search }); return; }
    await self.clients.openWindow(target.href);
  })());
});
